function numDupDigitsAtMostN(n) {
  // List every number up to n whose digits are all different by growing them one digit at a time.
  let distinct = 0;
  const used = new Array(10).fill(false);
  const extend = (value) => {
    for (let d = value === 0 ? 1 : 0; d <= 9; d++) {
      if (used[d]) continue;
      const next = value * 10 + d;
      if (next > n) break;
      used[d] = true;
      distinct++;
      extend(next);
      used[d] = false;
    }
  };
  extend(0);
  return n - distinct;
}

