function generate(rand, size) {
  const pick = rand();
  if (size === 'large') {
    if (pick < 0.15) return [1000000000];
    // A number with up to nine all-different digits, or a random one near the limit.
    if (pick < 0.4) {
      const pool = [1, 2, 3, 4, 5, 6, 7, 8, 9, 0];
      for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
      if (pool[0] === 0) [pool[0], pool[1]] = [pool[1], pool[0]];
      return [Number(pool.slice(0, 9).join(''))];
    }
    return [100000000 + Math.floor(rand() * 900000001)];
  }
  // Small: tiny values, powers of ten and their neighbours, repeated digits, or moderate values.
  if (pick < 0.3) return [1 + Math.floor(rand() * 150)];
  if (pick < 0.5) {
    const power = 10 ** (1 + Math.floor(rand() * 5));
    return [Math.max(1, power + Math.floor(rand() * 3) - 1)];
  }
  if (pick < 0.65) {
    const digit = 1 + Math.floor(rand() * 9);
    return [Number(String(digit).repeat(1 + Math.floor(rand() * 5)))];
  }
  return [1 + Math.floor(rand() * 200000)];
}
